  same(draft,fixture.get("finalDraft"),"full final state");same(prepare(input,draft,input),fixture.get("payload"),"full final changes");same(prepare(input,draft,fixture.getJSONObject("quoteRefreshed")),fixture.get("payload"),"quote refresh allowed without stale quote write");check(prepare(input,input,input).getBoolean("noChange"),"noop");final JSONObject completed=draft;
  for(String op:new String[]{"renameGroup","setColor","deleteGroup","addMember","removeMember","moveGroup","moveMember"})rejects(()->apply(input,object("op",op,"groupId","ths:42","name","新名","color","#123456","instrumentId","SZ:stock:600000","to",0)),"readonly "+op);
  rejects(()->apply(input,object("op","addMember","groupId","local:2","instrumentId","600000")),"bare code");rejects(()->apply(input,object("op","addMember","groupId","local:2","instrumentId","SH:stock:600000")),"same group duplicate");rejects(()->apply(input,object("op","moveGroup","groupId","local:2","to",1.5)),"fractional order");rejects(()->apply(input,object("op","addGroup","groupId","local:2","name","x","color","")),"duplicate stable ID");rejects(()->apply(input,object("op","setColor","groupId","local:2","color","red")),"invalid color");for(String name:new String[]{"","  "," x","x\n",new String(new char[61]).replace('\0','x')})rejects(()->apply(input,object("op","renameGroup","groupId","local:2","name",name)),"invalid name");
