  bad=copy(input);bad.getJSONArray("groups").getJSONObject(2).put("readOnly",false);final JSONObject forged=bad;rejects(()->prepare(input,forged,input),"readonly state forgery");bad=copy(input);bad.getJSONArray("groups").getJSONObject(0).remove("sourceMeta");final JSONObject unknown=bad;rejects(()->prepare(input,unknown,input),"unknown group metadata preserved");bad=copy(input);bad.getJSONArray("instruments").getJSONObject(0).put("quote",object("price",42));final JSONObject quote=bad;rejects(()->prepare(input,quote,input),"draft quote overwrite rejected");
