  WatchlistWorkspaceScreen screen=new WatchlistWorkspaceScreen(context,reader,saver);screen.previewChanges();screen.commitChanges();check(writes[0]==0,"noop no save");screen.applyOperation(object("op","renameGroup","groupId","local:1","name","UI草稿"));check(writes[0]==0&&screen.back(),"draft exit guard");screen.cancelChanges();same(screen.draftSnapshot(),fixture.get("input"),"cancel no write");
  EditText name=(EditText)screen.findViewWithTag("watchWorkspaceName");name.setText("未确认输入");rejects(screen::previewChanges,"raw input preview guard");Bundle inputState=screen.saveState();WatchlistWorkspaceScreen inputRestored=new WatchlistWorkspaceScreen(context,reader,saver);inputRestored.restoreState(inputState);check(((EditText)inputRestored.findViewWithTag("watchWorkspaceName")).getText().toString().equals("未确认输入"),"unconfirmed input restore");screen.cancelChanges();
  ((EditText)screen.findViewWithTag("watchWorkspaceNewName")).setText("UI空组");click(screen,"watchWorkspaceAddGroup");check(screen.draftSnapshot().getJSONArray("groups").length()==4,"actual new empty group");Spinner picker=(Spinner)screen.findViewWithTag("watchWorkspaceRoster");check(picker.getSelectedItemPosition()==0,"no automatic instrument choice");picker.setSelection(2);click(screen,"watchWorkspaceAddMember");same(screen.draftSnapshot().getJSONArray("groups").getJSONObject(3).get("memberIds"),new JSONArray().put("SH:etf:600000"),"exact same-code ETF selection");
  JSONObject view=screen.saveViewState();check(!view.toString().contains("synthetic-offline"),"no raw quote history in state");Bundle saved=screen.saveState();Parcel parcel=Parcel.obtain();saved.writeToParcel(parcel,0);check(parcel.dataSize()<128*1024,"bounded Binder actual parcel");parcel.recycle();WatchlistWorkspaceScreen restored=new WatchlistWorkspaceScreen(context,reader,saver);restored.restoreState(saved);same(restored.draftSnapshot().get("groups"),screen.draftSnapshot().get("groups"),"reopen exact draft");rejects(restored::commitChanges,"restored preview not save authorization");restored.previewChanges();live[0].put("revision","external");rejects(restored::commitChanges,"actual stale commit");check(writes[0]==0,"concurrent no callback");live[0]=copy(fixture.getJSONObject("input"));restored.previewChanges();restored.commitChanges();check(writes[0]==1&&live[0].getJSONArray("groups").length()==4,"explicit actual save");same(live[0].get("instruments"),fixture.getJSONObject("input").get("instruments"),"quote0/unknown/provenance unchanged");check(!restored.back(),"clean saved exit");
  restored.setDarkTheme(true);float density=context.getResources().getDisplayMetrics().density;int w=Math.round(900*density),h=Math.round(180*density);restored.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));restored.layout(0,0,w,h);check(restored.findViewWithTag("watchWorkspaceViewport").getMeasuredHeight()>=Math.round(80*density),"compact viewport");
  final int[]attempts={0};WatchlistWorkspaceScreen uncertain=new WatchlistWorkspaceScreen(context,reader,p->{attempts[0]++;return copy(live[0]);});uncertain.applyOperation(object("op","renameGroup","groupId","local:1","name","坏回执"));uncertain.previewChanges();rejects(uncertain::commitChanges,"invalid receipt");rejects(uncertain::commitChanges,"unknown outcome cannot retry");WatchlistWorkspaceScreen uncertainRestored=new WatchlistWorkspaceScreen(context,reader,saver);uncertainRestored.restoreState(uncertain.saveState());rejects(uncertainRestored::previewChanges,"unknown outcome survives reopen");check(attempts[0]==1&&uncertainRestored.back(),"unknown exit guard");
  JSONObject bigInput=copy(fixture.getJSONObject("input"));String large=new String(new char[26000]).replace('\0','研')+"📚";bigInput.getJSONArray("groups").getJSONObject(0).getJSONObject("sourceMeta").put("fullOriginal",large);WatchlistWorkspaceScreen big=new WatchlistWorkspaceScreen(context,()->copy(bigInput),p->{throw new Exception("large UI check must not write");});big.applyOperation(object("op","renameGroup","groupId","local:1","name","大原文草稿"));big.previewChanges();TextView readerText=(TextView)big.findViewWithTag("watchWorkspaceEvidence");String first=readerText.getText().toString();check(first.length()<=24100,"bounded complete reader segment");click(big,"watchWorkspaceReadNext");check(!readerText.getText().toString().equals(first)&&readerText.getText().length()<=24100,"next segment actual full reader");click(big,"watchWorkspaceReadPrevious");check(readerText.getText().toString().equals(first),"reader previous exact");rejects(big::saveState,"oversize Binder explicitly refused");JSONObject full=big.saveViewState();WatchlistWorkspaceScreen bigRestored=new WatchlistWorkspaceScreen(context,()->copy(bigInput),saver);bigRestored.restoreViewState(full);same(bigRestored.draftSnapshot().get("groups"),big.draftSnapshot().get("groups"),"full host JSON state retains big originals without truncation");return "WatchlistWorkspace Android screen PASS "+count;
